Wang_2024_atezolizumab_carboplatin_nabpaclitaxel_qsp <- function() {
  description <- paste(
    "QSP. Quantitative systems pharmacology model of non-small-cell lung cancer",
    "(NSCLC) describing the triple combination of the anti-PD-L1 checkpoint",
    "inhibitor atezolizumab with carboplatin and nab-paclitaxel, extended from",
    "the published immuno-oncology QSP platform. Four physiological compartments",
    "(central, peripheral, tumour, tumour-draining lymph node) plus APC",
    "endosomal and surface compartments, two immunological-synapse compartments",
    "and a separate three-compartment Michaelis-Menten PK model for",
    "nab-paclitaxel. Covers naive and activated CD4+/CD8+ T cell trafficking and",
    "proliferation, logistic tumour growth against a dynamic vasculature-driven",
    "carrying capacity with a drug-sensitive and a chemo-resistant cancer clone,",
    "self-antigen and neo-antigen release, uptake, endosomal processing and",
    "MHC-I presentation, TCR-mediated activation, PD-1/PD-L1/PD-L2 checkpoint",
    "binding with atezolizumab blockade, CTLA-4/CD28/CD80/CD86 co-signalling,",
    "MDSC recruitment with arginase-I and nitric-oxide suppression,",
    "Th-to-Treg transdifferentiation, TGF-beta / IFN-gamma / IL-2 / CCL2",
    "dynamics, and the cytotoxic plus anti-angiogenic effects of nab-paclitaxel",
    "and carboplatin. 140 ODE states, 55 algebraic (repeated- and",
    "initial-assignment) rules and 247 parameters, translated from the",
    "SimBiology export in Supplementary Tables S2-S7. Deterministic mechanism",
    "model: the authors generated virtual patients by Latin hypercube sampling",
    "of the 26 parameter distributions in Supplementary Table S1 rather than by",
    "fitting IIV or residual error, so no etas and no error model are encoded.",
    sep = " "
  )
  reference <- paste(
    "Wang CY, Dai HR, Tan YP, Yang DH, Niu XM, Han L, Wang W, Ma LL, Julku A,",
    "Jiao Z. Development and Evaluation of a Quantitative Systems Pharmacology",
    "Model for Mechanism Interpretation and Efficacy Prediction of Atezolizumab",
    "in Combination with Carboplatin and Nab-Paclitaxel in Patients with",
    "Non-Small-Cell Lung Cancer. Pharmaceuticals (Basel). 2024;17(2):238.",
    "doi:10.3390/ph17020238.",
    sep = " "
  )
  vignette <- "Wang_2024_atezolizumab_carboplatin_nabpaclitaxel_qsp"

  units <- list(
    time          = "day",
    dosing        = "nmol",
    concentration = "nmol/L"
  )

  covariateData <- list()

  population <- list(
    species       = "human (in silico virtual cohort)",
    n_subjects    = 1000L,
    n_studies     = 1L,
    disease_state = "advanced squamous / non-squamous non-small-cell lung cancer, first line",
    dose_range    = paste(
      "Atezolizumab 1200 mg IV on day 1 of each 21-day cycle (with 840 mg Q2W",
      "and 1680 mg Q4W evaluated as alternative regimens), carboplatin at an",
      "AUC of 6 mg/mL/min IV on day 1, and nab-paclitaxel 100 mg/m2 IV on days",
      "1, 8 and 15.",
      sep = " "
    ),
    notes = paste(
      "Calibrated and evaluated against the IMpower131 trial (NCT02367794).",
      "Virtual cohorts were generated by Latin hypercube sampling of the 26",
      "parameter distributions in Supplementary Table S1 (500 patients for the",
      "objective-response-rate and duration-of-response evaluation, 1000 per",
      "regimen for the alternative-dosing comparison and the biomarker",
      "analysis). Pre-treatment tumour diameter is log-normal with a geometric",
      "mean of 2.5 cm. Treatment duration 400 days with tumour assessment every",
      "8 weeks, scored by RECIST v1.1. Immune-system parameters were assumed",
      "shared with the authors' earlier triple-negative-breast-cancer platform;",
      "only the cancer-cell dynamics parameters were re-estimated for NSCLC.",
      sep = " "
    )
  )

  ini({
    # ---- Compartment capacities (Supplementary Table S2) ----
    vol_V_C <- fixed(5); label("Capacity of compartment V_C [dm^3]")  # Table S2 (V_C = 5 liter)
    vol_V_P <- fixed(60); label("Capacity of compartment V_P [dm^3]")  # Table S2 (V_P = 60 liter)
    # V_T is a repeated assignment (Table S6 rule 1), not a constant: stored value 1e-06 milliliter
    vol_V_LN <- fixed(0.00137444678595); label("Capacity of compartment V_LN [dm^3]")  # Table S2 (V_LN = 1374.45 millimeter^3)
    vol_V_e <- fixed(4e-16); label("Capacity of compartment V_e [dm^3]")  # Table S2 (V_e = 4e-16 litre)
    vol_A_e <- fixed(1.5e-09); label("Capacity of compartment A_e [dm^2]")  # Table S2 (A_e = 15 micrometer^2)
    vol_A_s <- fixed(9e-08); label("Capacity of compartment A_s [dm^2]")  # Table S2 (A_s = 900 micrometer^2)
    vol_syn_T_C1 <- fixed(3.78e-09); label("Capacity of compartment syn_T_C1 [dm^2]")  # Table S2 (syn_T_C1 = 37.8 micrometer^2)
    vol_syn_T_APC <- fixed(3.78e-09); label("Capacity of compartment syn_T_APC [dm^2]")  # Table S2 (syn_T_APC = 37.8 micrometer^2)
    vol_V_1 <- fixed(15.8); label("Capacity of compartment V_1 [dm^3]")  # Table S2 (V_1 = 15.8 liter)
    vol_V_2 <- fixed(1650); label("Capacity of compartment V_2 [dm^3]")  # Table S2 (V_2 = 1650 liter)
    vol_V_3 <- fixed(75.4); label("Capacity of compartment V_3 [dm^3]")  # Table S2 (V_3 = 75.4 liter)

    NAVG_nmol <- fixed(6.0221409e14); label("Avogadro constant, molecule per nanomole [molecule/nmol]")  # physical constant; carries the molecule <-> nmol conversion

    # ---- Model parameters (Supplementary Table S4) ----
    # Values are converted to the canonical unit system (day / L / dm^2 / nmol / cell / ug);
    # each trailing comment records the value and unit exactly as tabulated in Table S4.
    k_cell_clear <- fixed(0.1); label("Rate of dead cell clearance from tumour compartment (estimated) [1/day]")  # Table S4 (k_cell_clear = 0.1 1/day)
    cell <- fixed(1); label("unit parameter for calculation [cell]")  # Table S4 (cell = 1 cell)
    day <- fixed(1); label("unit parameter for calculation [day]")  # Table S4 (day = 1 day)
    vol_cell <- fixed(2.52731128245e-12); label("Average volume of cancer cell Volume of a cancer cell calculated based on cancer cell diameter (Jafarnejad 2019 PMID: 31236847) [dm^3/cell]")  # Table S4 (vol_cell = 2527.31 micrometer^3/cell)
    vol_Tcell <- fixed(1.750157098e-13); label("Average volume of T cells Volume of a T cell calculated based on the average T cell diameter (Chapman 1981, PMID: 6975780) [dm^3/cell]")  # Table S4 (vol_Tcell = 175.016 micrometer^3/cell)
    Ve_T <- fixed(0.37); label("Void fraction of the tumor (Finley 2012, PMID: 22547351) [1]")  # Table S4 (Ve_T = 0.37 dimensionless)
    k_C1_growth <- fixed(0.012); label("Cancer cell growth rate (doi: 10.1208/s12248-019-0302-5) [1/day]")  # Table S4 (k_C1_growth = 0.012 1/day)
    k_C1_death <- fixed(0.0001); label("Cancer cell death rate from innate immune cells (PMID: 3156189) [1/day]")  # Table S4 (k_C1_death = 0.0001 1/day)
    initial_tumour_diameter <- fixed(0.25); label("Pre-treatment tumor diameter [dm]")  # Table S4 (initial_tumour_diameter = 2.5 centimeter)
    div_T0 <- fixed(1160000); label("T Cell Diversity (Robins 2009, PMID: 19706884) [1]")  # Table S4 (div_T0 = 1.16e+06 dimensionless)
    n_T0_clones <- fixed(250); label("Number of T cell clones (Jafarnejad 2019 PMID: 31236847) [1]")  # Table S4 (n_T0_clones = 250 dimensionless)
    q_nT0_LN_in <- fixed(0.1); label("Rate of naive T cell transport into the LN calculated based on the steady-state naive T cell level in healthy individuals (Autissier 2010, PMID: 20099249) [1/day]")  # Table S4 (q_nT0_LN_in = 0.1 1/day)
    q_T0_LN_out <- fixed(24); label("Rate of activated T cell transport out of the LN (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (q_T0_LN_out = 24 1/day)
    q_nT0_LN_out <- fixed(2.88); label("Rate of naive T cell transport out of the LN (Mandl 2012, PMID: 23071319) [1/day]")  # Table S4 (q_nT0_LN_out = 2.88 1/day)
    k_T0_act <- fixed(5); label("T0 activation rate (De Boer and Perelson 1995, PMID: 7475092; Robertson-Tessi 2012, PMID: 22051568) [1/day]")  # Table S4 (k_T0_act = 5 1/day)
    k_T0_pro <- fixed(1); label("T0 proliferation rate (Marchingo 2014, PMID: 25430770) [1/day]")  # Table S4 (k_T0_pro = 1 1/day)
    k_T0_death <- fixed(0.01); label("T0 death rate (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (k_T0_death = 0.01 1/day)
    q_T0_P_in <- fixed(3507.84); label("rate of T0 transport into the peripheral compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day]")  # Table S4 (q_T0_P_in = 2.436 1/minute)
    q_T0_P_out <- fixed(24); label("rate of T0 transport out of the peripheral compartment (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (q_T0_P_out = 24 1/day)
    q_T0_T_in <- fixed(83.52); label("rate of T0 transport into the tumor compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day*dm^3]")  # Table S4 (q_T0_T_in = 5.8e-05 1/(centimeter^3*minute))
    q_nT0_P_in <- fixed(254.016); label("rate of nT0 transport into the peripheral compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day]")  # Table S4 (q_nT0_P_in = 0.1764 1/minute)
    q_nT0_P_out <- fixed(5.1); label("rate of nT0 transport out of the peripheral compartment calculated based on steady-state naive T cell density in healthy individuals (Autissier 2010, PMID: 20099249) [1/day]")  # Table S4 (q_nT0_P_out = 5.1 1/day)
    Q_nT0_thym <- fixed(70000000); label("Thymic output of nT0 (Bains 2009, PMID: 19179300; Yeh 2017, PMID: 28912973) [cell/day]")  # Table S4 (Q_nT0_thym = 7e+07 cell/day)
    k_nT0_pro <- fixed(320000000); label("rate of nT0 proliferation (Braber 2012, PMID: 22365666) [cell/day]")  # Table S4 (k_nT0_pro = 3.2e+08 cell/day)
    K_nT0_pro <- fixed(1000000000); label("half-maximal peripheral proliferation of of nT0 (Braber 2012, PMID: 22365666) [cell]")  # Table S4 (K_nT0_pro = 1e+09 cell)
    k_nT0_death <- fixed(0.002); label("rate of nT0 death (Braber 2012, PMID: 22365666) [1/day]")  # Table S4 (k_nT0_death = 0.002 1/day)
    k_IL2_deg <- fixed(288); label("rate of IL2 degradation (Lotze 1985, PMID: 3871099) [1/day]")  # Table S4 (k_IL2_deg = 0.2 1/minute)
    k_IL2_cons <- fixed(0.000144); label("rate of IL2 consumption by T cells (Lotze 1985, PMID: 3871099) [nmol/day*cell]")  # Table S4 (k_IL2_cons = 6e-06 nanomole/cell/hour)
    k_IL2_sec <- fixed(0.00072); label("rate of IL2 secretion from T cells (Han 2012, PMID: 22160692; Thurley 2015, PMID: 25923703; Liu 2001) [nmol/day*cell]")  # Table S4 (k_IL2_sec = 3e-05 nanomole/cell/hour)
    IL2_50 <- fixed(0.32); label("T cell activation half-maximal IL2 concentration (Marchingo 2014, PMID: 25430770) [nmol/dm^3]")  # Table S4 (IL2_50 = 0.32 nanomolarity)
    IL2_50_Treg <- fixed(0.32); label("Treg activation half-maximal IL2 concentration (Wang and Smith 1987, PMID: 3116143,doi: 10.1084/jem.166.4.1055) [nmol/dm^3]")  # Table S4 (IL2_50_Treg = 0.32 nanomolarity)
    N0 <- fixed(2); label("numer of activated T cell generation by TCR signaling only(doi: 10.1126/science.1260044) [1]")  # Table S4 (N0 = 2 dimensionless)
    N_costim <- fixed(3); label("numer of activated T cell generation by co-stimulatory signaling only (Marchingo 2014, PMID: 25430770) [1]")  # Table S4 (N_costim = 3 dimensionless)
    N_IL2_CD8 <- fixed(11); label("maximum number of activated T cell generations due to IL2 (Marchingo 2014, PMID: 25430770) [1]")  # Table S4 (N_IL2_CD8 = 11 dimensionless)
    N_IL2_CD4 <- fixed(8); label("maximum number of activated T cell generations due to IL2 (Marchingo 2014, PMID: 25430770) [1]")  # Table S4 (N_IL2_CD4 = 8 dimensionless)
    k_Treg <- fixed(0.1); label("Rate of T cell death by Tregs (estimated) [1/day]")  # Table S4 (k_Treg = 0.1 1/day)
    div_T1 <- fixed(1110000); label("T Cell Diversity (Robins 2009, PMID: 19706884) [1]")  # Table S4 (div_T1 = 1.11e+06 dimensionless)
    n_T1_clones <- fixed(92); label("Number of T cell clones (Jafarnejad 2019 PMID: 31236847)) [1]")  # Table S4 (n_T1_clones = 92 dimensionless)
    q_nT1_LN_in <- fixed(0.076); label("Rate of naive T cell transport into the LN calculated based on the steady-state naive T cell level in healthy individuals (Autissier 2010, PMID: 20099249) [1/day]")  # Table S4 (q_nT1_LN_in = 0.076 1/day)
    q_T1_LN_out <- fixed(24); label("Rate of activated T cell transport out of the LN (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (q_T1_LN_out = 24 1/day)
    q_nT1_LN_out <- fixed(1.8); label("Rate of naive T cell transport out of the LN (Mandl 2012, PMID: 23071319) [1/day]")  # Table S4 (q_nT1_LN_out = 1.8 1/day)
    k_T1_act <- fixed(23); label("T1 activation rate (De Boer and Perelson 1995, PMID: 7475092; Robertson-Tessi 2012, PMID: 22051568) [1/day]")  # Table S4 (k_T1_act = 23 1/day)
    k_T1_pro <- fixed(1); label("T1 proliferation rate (Marchingo 2014, PMID: 25430770) [1/day]")  # Table S4 (k_T1_pro = 1 1/day)
    k_T1_death <- fixed(0.01); label("T1 death rate (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (k_T1_death = 0.01 1/day)
    q_T1_P_in <- fixed(3507.84); label("rate of T1 transport into the peripheral compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day]")  # Table S4 (q_T1_P_in = 2.436 1/minute)
    q_T1_P_out <- fixed(24); label("rate of T1 transport out of the peripheral compartment (De Boer and Perelson 1995, PMID: 7475092) [1/day]")  # Table S4 (q_T1_P_out = 24 1/day)
    q_T1_T_in <- fixed(83.52); label("rate of T1 transport into the tumor compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day*dm^3]")  # Table S4 (q_T1_T_in = 5.8e-05 1/(centimeter^3*minute))
    q_nT1_P_in <- fixed(254.016); label("rate of nT1 transport into the peripheral compartment calculated based on T cell transmigration rate (Zhu 1996, PMID: 8706023) and T cell adhesion density (Zhu 1996, PMID: 8706023) [1/day]")  # Table S4 (q_nT1_P_in = 0.1764 1/minute)
    q_nT1_P_out <- fixed(5.1); label("rate of nT1 transport out of the peripheral compartment calculated based on steady-state naive T cell density in healthy individuals (Autissier 2010, PMID: 20099249) [1/day]")  # Table S4 (q_nT1_P_out = 5.1 1/day)
    Q_nT1_thym <- fixed(35000000); label("Thymic output of nT1 (Bains 2009, PMID: 19179300; Ye 2002, PMID: 11994448) [cell/day]")  # Table S4 (Q_nT1_thym = 3.5e+07 cell/day)
    k_nT1_pro <- fixed(320000000); label("rate of nT1 proliferation (Braber 2012, PMID: 22365666) [cell/day]")  # Table S4 (k_nT1_pro = 3.2e+08 cell/day)
    K_nT1_pro <- fixed(1000000000); label("half-maximal peripheral proliferation of of nT1 (Braber 2012, PMID: 22365666) [cell]")  # Table S4 (K_nT1_pro = 1e+09 cell)
    k_nT1_death <- fixed(0.002); label("rate of nT1 death (Braber 2012, PMID: 22365666) [1/day]")  # Table S4 (k_nT1_death = 0.002 1/day)
    k_T1 <- fixed(0.1); label("Rate of T cell exhaustion by cancer cells (estimated) [1/day]")  # Table S4 (k_T1 = 0.1 1/day)
    k_C_T1 <- fixed(4); label("Rate of cancer cell death by T cells (Robertson-Tessi 2012, PMID: 22051568) [1/day]")  # Table S4 (k_C_T1 = 4 1/day)
    k_APC_mat <- fixed(1.5); label("Maximum rate of APC maturation (Chen 2014, PMID: 25184733) [1/day]")  # Table S4 (k_APC_mat = 1.5 1/day)
    k_APC_mig <- fixed(4); label("Rate of APC migration (Russo Halin 2016, PMID: 26876174) [1/day]")  # Table S4 (k_APC_mig = 4 1/day)
    k_APC_death <- fixed(0.01); label("Rate of APC death (Marino and Kirschner 2004, PMID: 15038983) [1/day]")  # Table S4 (k_APC_death = 0.01 1/day)
    k_mAPC_death <- fixed(0.02); label("Rate of mAPC death(Marino and Kirschner 2004, PMID: 15038983) [1/day]")  # Table S4 (k_mAPC_death = 0.02 1/day)
    APC0_T <- fixed(400000000); label("Steady state density of CD103+ APCs in the tumor, calculated to fit basal APC equal to 26000/cm^3 from (Lavin 2017, PMID: 28475900) [cell/dm^3]")  # Table S4 (APC0_T = 400000 cell/milliliter)
    APC0_LN <- fixed(1200000000); label("Steady state density of all APC subtypes in the LN (Catron 2004, PMID: 15357945)- divided by 10 to only take CD103+ based on (Lavin 2017, PMID: 28475900) [cell/dm^3]")  # Table S4 (APC0_LN = 1.2e+06 cell/milliliter)
    k_c <- fixed(2); label("Cytokine rate constant (Chen 2014, PMID: 25184733) [1/day]")  # Table S4 (k_c = 2 1/day)
    c0 <- fixed(1); label("Baseline cytokine concentration (Chen 2014, PMID: 25184733) [nmol/dm^3]")  # Table S4 (c0 = 1e-09 molarity)
    c50 <- fixed(1); label("Cytokine concentration for half-maximal APC maturation (Chen 2014, PMID: 25184733) [nmol/dm^3]")  # Table S4 (c50 = 1e-09 molarity)
    DAMPs <- fixed(1.34e-05); label("Concentration of cytokines released per dying cancer cell (Milo 2013, PMID: 24114984, Ponomarenko 2016, PMID: 27298622) [nmol/cell]")  # Table S4 (DAMPs = 1.34e-14 mole/cell)
    n_sites_APC <- fixed(10); label("Maxium number of T Cells an APC can interact with (De Boer and Perelson 1995, PMID: 7475092) [1]")  # Table S4 (n_sites_APC = 10 dimensionless)
    kin <- fixed(14.4); label("Rate of MHC internalization (Chen 2014, PMID: 25184733) [1/day]")  # Table S4 (kin = 14.4 1/day)
    kout <- fixed(28.8); label("Rate of MHC externalization (Chen 2014, PMID: 25184733) [1/day]")  # Table S4 (kout = 28.8 1/day)
    k_P0_up <- fixed(14.4); label("Rate of antigen uptake by APCs (Chen 2014, PMID: 25184733) [1/day*cell]")  # Table S4 (k_P0_up = 14.4 1/day/cell)
    k_xP0_deg <- fixed(2); label("Rate of extracellular antigen degradation (Palsson 2013, PMID: 24074340) [1/day]")  # Table S4 (k_xP0_deg = 2 1/day)
    k_P0_deg <- fixed(17.28); label("Rate of endosomal antigen degradation (Chen 2014, PMID: 25184733) [1/day]")  # Table S4 (k_P0_deg = 17.28 1/day)
