    p0_50 <- fixed(4.39296049517e-10); label("calculated based on the number of molecules for half-maximal T cell activation (Kimachi 1997, PMID: 9464819) and synapse surface area [nmol/dm^2]")  # Table S4 (p0_50 = 2.6455e-05 molecule/micrometer^2)
    P0_C1 <- fixed(0.00054); label("Concentration of P0 in C1 (estimated by 2.7e6 proteins/um^3 in a cancer cell (Milo 2013, PMID: 24114984) * cancer cell volume / Avogadro constant) [nmol/cell]")  # Table S4 (P0_C1 = 5.4e-13 mole/cell)
    P0_C2 <- fixed(0.00054); label("Concentration of P0 in C2 (estimated by 2.7e6 proteins/um^3 in a cancer cell (Milo 2013, PMID: 24114984) * cancer cell volume / Avogadro constant) [nmol/cell]")  # Table S4 (P0_C2 = 5.4e-13 mole/cell)
    A_Tcell <- fixed(1.5131041193e-08); label("Surface area of the T cell calculated based on the average T cell diameter (Chapman 1981, PMID: 6975780) [dm^2]")  # Table S4 (A_Tcell = 151.31 micrometer^2)
    A_cell <- fixed(8.97270277792e-08); label("Surface area of the Cancer cell calculated based on the average cancer cell diameter (Jafarnejad 2019 PMID: 31236847) [dm^2]")  # Table S4 (A_cell = 897.27 micrometer^2)
    A_APC <- fixed(9e-08); label("Surface area of the APC (Agrawal and Linderman 1996, PMID: 8944895) [dm^2]")  # Table S4 (A_APC = 900 micrometer^2)
    k_M1p0_TCR_on <- fixed(5203129616.64); label("Rate of TCR binding to MHC-peptide complex (Lever 2014, PMID: 25145757) [dm^2/day*nmol]")  # Table S4 (k_M1p0_TCR_on = 1 1/(second*molecule/micrometer^2))
    k_M1p0_TCR_off <- fixed(86400); label("Rate of TCR unbinding from MHC-peptide complex (Lever 2014, PMID: 25145757) [1/day]")  # Table S4 (k_M1p0_TCR_off = 1 1/second)
    k_M1p0_TCR_p <- fixed(86400); label("Rate of MHC-peptide-TCR complex modification (Lever 2014, PMID: 25145757) [1/day]")  # Table S4 (k_M1p0_TCR_p = 1 1/second)
